html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--g-color-base-background);
}

.layout {
  display: flex;
  height: 100vh;
  overflow: hidden;
}

/* ---------- Sidebar ---------- */

.sidebar {
  flex: 0 0 auto;
  width: 232px;
  height: 100%;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--g-color-line-generic);
  background: var(--g-color-base-background);
  transition: width 0.2s ease;
  overflow: hidden;
}

.sidebar_collapsed {
  width: 68px;
}

.sidebar__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px;
  min-height: 64px;
}

.sidebar__logo-mark {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  color: var(--g-color-text-light-primary);
  background: var(--g-color-base-brand);
}

.sidebar__logo-text {
  white-space: nowrap;
}

.sidebar__nav {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px;
}

