  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 14px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--g-color-text-secondary);
  font: inherit;
  font-size: var(--g-text-body-2-font-size);
  line-height: var(--g-text-body-2-line-height);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}

.sidebar_collapsed .sidebar__item {
  justify-content: center;
  padding: 9px;
}

.sidebar__item:hover {
  background: var(--g-color-base-simple-hover);
  color: var(--g-color-text-primary);
}

.sidebar__item_active,
.sidebar__item_active:hover {
  background: var(--g-color-base-selection);
  color: var(--g-color-text-primary);
}

.sidebar__item-label {
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar__footer {
  padding: 8px;
  border-top: 1px solid var(--g-color-line-generic);
}

.sidebar_collapsed .sidebar__toggle {
  width: 100%;
  justify-content: center;
}

/* ---------- Main ---------- */

.main {
  flex: 1 1 auto;
  min-width: 0;
  overflow-y: auto;
  padding: 24px 28px 48px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.main__header {
  display: flex;
  align-items: center;
}

/* ---------- Stat tiles ---------- */

.stat-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.stat-tile {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-tile__value {
  color: var(--g-color-text-primary);
}

.placeholder {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 560px;
}

/* ---------- Orders table ---------- */

.orders-table {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}

