  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.orders-table__toolbar-info {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.orders-table__toolbar-controls {
  display: flex;
  align-items: center;
  gap: 16px;
}

.orders-table__scroll {
  overflow: auto;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 12px;
  background: var(--g-color-base-background);
}

.orders-table__table {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.orders-table__head-cell {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 10px 14px;
  background: var(--g-color-base-generic);
  border-bottom: 1px solid var(--g-color-line-generic);
  font-size: var(--g-text-body-1-font-size);
  font-weight: 500;
  color: var(--g-color-text-secondary);
  white-space: nowrap;
  user-select: none;
}

.orders-table__head-cell_draggable {
  cursor: grab;
}

.orders-table__head-cell_dragging {
  opacity: 0.4;
}

.orders-table__head-cell_drop-target {
  box-shadow: inset 2px 0 0 var(--g-color-line-brand);
  background: var(--g-color-base-selection);
}

.orders-table__head-content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.orders-table__grip {
  color: var(--g-color-text-hint);
}

.orders-table__cell {
  padding: 10px 14px;
  border-bottom: 1px solid var(--g-color-line-generic-solid);
  font-size: var(--g-text-body-1-font-size);
  color: var(--g-color-text-primary);
  white-space: nowrap;
}

.orders-table__cell_check {
  width: 44px;
  text-align: center;
}

.orders-table__row {
  cursor: pointer;
  transition: background 0.1s ease;
}

.orders-table__row:hover {
  background: var(--g-color-base-simple-hover);
}

.orders-table__row_selected,
.orders-table__row_selected:hover {
  background: var(--g-color-base-selection);
}

.orders-table__group-row {
  cursor: pointer;
  background: var(--g-color-base-float-announcement);
}

.orders-table__group-cell {
  padding: 8px 14px;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.orders-table__group-cell {
  vertical-align: middle;
}

.orders-table__group-cell > * {
  vertical-align: middle;
}

.orders-table__group-cell {
  white-space: nowrap;
}

.orders-table__group-cell .g-icon {
  margin-right: 6px;
}

.orders-table__group-cell .g-label {
  margin-right: 10px;
}

